import {
    TransportWaybillDto,
    TransportWaybillPartyRole,
    TransportWaybillProcessingStatus,
    transportWaybillPartyRoleLabels,
    transportWaybillStatusLabels,
} from "../../models/transportWaybill";

export const supportedTransportWaybillFileExtensions = [".pdf", ".jpg", ".jpeg", ".png", ".webp"];

export const emptyValue = "-";

export const parseOptionalPositiveNumber = (value: string) => {
    const trimmedValue = value.trim();

    if (!trimmedValue) {
        return undefined;
    }

    const numberValue = Number(trimmedValue);

    if (!Number.isInteger(numberValue) || numberValue <= 0) {
        return null;
    }

    return numberValue;
};

export const isSupportedTransportWaybillFile = (file: File | null) =>
    Boolean(
        file &&
        supportedTransportWaybillFileExtensions.some((extension) =>
            file.name.toLowerCase().endsWith(extension),
        ),
    );

export const formatFileSize = (bytes: number | null | undefined) => {
    if (!bytes) {
        return emptyValue;
    }

    if (bytes < 1024) {
        return `${bytes} B`;
    }

    if (bytes < 1024 * 1024) {
        return `${(bytes / 1024).toFixed(1)} KB`;
    }

    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
};

export const formatNullableNumber = (
    value: number | null | undefined,
    locale: string,
    options?: Intl.NumberFormatOptions,
) => {
    if (value === null || value === undefined || Number.isNaN(value)) {
        return emptyValue;
    }

    return new Intl.NumberFormat(locale, options).format(value);
};

export const formatCurrency = (value: number | null | undefined, locale: string) =>
    formatNullableNumber(value, locale, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    });

export const formatConfidence = (value: number | null | undefined, locale: string) => {
    if (value === null || value === undefined || Number.isNaN(value)) {
        return emptyValue;
    }

    const normalizedValue = value <= 1 ? value : value / 100;

    return new Intl.NumberFormat(locale, {
        style: "percent",
        maximumFractionDigits: 0,
    }).format(normalizedValue);
};

export const formatDate = (value: string | null | undefined, locale: string) => {
    if (!value) {
        return emptyValue;
    }

    const dateOnlyMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    const date = dateOnlyMatch
        ? new Date(Number(dateOnlyMatch[1]), Number(dateOnlyMatch[2]) - 1, Number(dateOnlyMatch[3]))
        : new Date(value);

    if (Number.isNaN(date.getTime())) {
        return value;
    }

    return new Intl.DateTimeFormat(locale, {
        day: "2-digit",
        month: "2-digit",
        year: "numeric",
    }).format(date);
};

export const formatDateTime = (value: string | null | undefined, locale: string) => {
    if (!value) {
        return emptyValue;
    }

    const date = new Date(value);

    if (Number.isNaN(date.getTime())) {
        return value;
    }

    return new Intl.DateTimeFormat(locale, {
        day: "2-digit",
        month: "2-digit",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
    }).format(date);
};

export const getWaybillStatusLabel = (waybill: Pick<TransportWaybillDto, "status" | "statusName">) =>
    waybill.statusName || transportWaybillStatusLabels[waybill.status] || String(waybill.status);

export const getPartyRoleLabel = (role: TransportWaybillPartyRole, roleName?: string | null) =>
    roleName || transportWaybillPartyRoleLabels[role] || String(role);

export const getDocumentTitle = (waybill: TransportWaybillDto) => {
    const documentNumber = [waybill.series, waybill.number].filter(Boolean).join(" ");

    if (documentNumber) {
        return documentNumber;
    }

    return waybill.file?.originalFileName || `#${waybill.id}`;
};

export const getFirstPartyName = (waybill: TransportWaybillDto, role: TransportWaybillPartyRole) =>
    waybill.parties.find((party) => party.role === role)?.name || emptyValue;

export const statusTone: Record<TransportWaybillProcessingStatus, {background: string; color: string}> = {
    [TransportWaybillProcessingStatus.Uploaded]: {
        background: "var(--color-primary-soft)",
        color: "var(--color-primary)",
    },
    [TransportWaybillProcessingStatus.Processing]: {
        background: "var(--color-warning-soft)",
        color: "var(--color-warning-text)",
    },
    [TransportWaybillProcessingStatus.Processed]: {
        background: "var(--color-success-soft)",
        color: "var(--color-success-text)",
    },
    [TransportWaybillProcessingStatus.Failed]: {
        background: "var(--color-danger-soft)",
        color: "var(--color-danger-text)",
    },
};
