const getStatusTone = (status: TransportWaybillProcessingStatus) =>
    statusTone[status] || statusTone[TransportWaybillProcessingStatus.Uploaded];

interface DetailFieldProps {
    label: string;
    value?: string | number | null;
}

const DetailField = ({label, value}: DetailFieldProps) => (
    <DetailItem>
        <DetailLabel>{label}</DetailLabel>
        <DetailValue>{value === null || value === undefined || value === "" ? emptyValue : value}</DetailValue>
    </DetailItem>
);

const groupPartiesByRole = (parties: TransportWaybillPartyDto[]) =>
    parties.reduce<Partial<Record<TransportWaybillPartyRole, TransportWaybillPartyDto[]>>>(
        (groups, party) => {
            const group = groups[party.role] || [];
            group.push(party);
            groups[party.role] = group;

            return groups;
        },
        {},
    );

const getCargoPointTitle = (point: TransportWaybillCargoPointDto, typeLabel: string) =>
    point.name || point.address || typeLabel || `#${point.id}`;

const getOperationTitle = (operation: TransportWaybillOperationDto, typeLabel: string) =>
    operation.performer || operation.method || typeLabel || `#${operation.id}`;

const getCargoPointTypeLabel = (point: TransportWaybillCargoPointDto) =>
    point.typeName || transportWaybillCargoPointTypeLabels[point.type] || String(point.type);

const getOperationTypeLabel = (operation: TransportWaybillOperationDto) =>
    operation.typeName || transportWaybillOperationTypeLabels[operation.type] || String(operation.type);

const getProcessingAttemptStatusLabel = (status: TransportWaybillProcessingStatus, statusName?: string | null) =>
    statusName || transportWaybillStatusLabels[status] || String(status);

interface WaybillHeaderProps {
    waybill: TransportWaybillDto;
    locale: string;
    goodsInvoice?: boolean;
}

const WaybillHeader = ({waybill, locale, goodsInvoice}: WaybillHeaderProps) => {
    const {t} = useTranslation();
    const tone = getStatusTone(waybill.status);

    return (
        <HeaderSurface>
            <HeaderTop>
                <PageTitleGroup>
                    <PageTitle>{goodsInvoice ? `Файл для прихода ${waybill.number || `#${waybill.id}`}` : getDocumentTitle(waybill)}</PageTitle>
                    <PageSubtitle>
                        {waybill.file?.originalFileName || t("Uploaded transport waybill")}
                    </PageSubtitle>
                </PageTitleGroup>
                <ToolbarActions>
                    {waybill.status === TransportWaybillProcessingStatus.Processed && <NavLink to={goodsInvoice ? `/invoices/${waybill.id}/approval` : `/invoices/${waybill.id}/approval`}  style={{textDecoration: "none"}}><CoreButton type="button" text={goodsInvoice ? "Предложение прихода" : "Оформить приход на склад"}/></NavLink>}
                    <StatusBadge $background={tone.background} $color={tone.color}>
                        {t(getWaybillStatusLabel(waybill))}
                    </StatusBadge>
                    <NavLink to={"/invoices"} style={{textDecoration: "none"}}>
                        <CoreButton
                            type="button"
                            text="К файлам для прихода"
                            leftIcon={<KeyboardReturnIcon/>}
                        />
                    </NavLink>
                </ToolbarActions>
            </HeaderTop>
            {waybill.errorMessage && (
                <Alert severity="error" icon={<ErrorOutlineOutlinedIcon/>}>
                    {waybill.errorMessage}
                </Alert>
            )}
            <FieldGrid>
                <DetailField label={t("Series")} value={waybill.series}/>
                <DetailField label={t("Number")} value={waybill.number}/>
                <DetailField label={t("Document date")} value={formatDate(waybill.documentDate, locale)}/>
                <DetailField label={t("Confidence")} value={formatConfidence(waybill.extractionConfidence, locale)}/>
                <DetailField label={t("Form")} value={[waybill.formName, waybill.formCode].filter(Boolean).join(" / ")}/>
                <DetailField label={t("Barcode")} value={waybill.barcode}/>
                <DetailField label={t("Release basis")} value={waybill.releaseBasis}/>
                {!goodsInvoice && <DetailField label={t("Reconsignment note")} value={waybill.reconsignmentNote}/>}
                <DetailField label={t("Order ID")} value={waybill.orderId}/>
                {!goodsInvoice && <DetailField label={t("Logistics trip ID")} value={waybill.logisticsTripId}/>}
                <DetailField label={t("Created")} value={formatDateTime(waybill.createdDateUtc, locale)}/>
                <DetailField label={t("Processed")} value={formatDateTime(waybill.processedDateUtc, locale)}/>
            </FieldGrid>
        </HeaderSurface>
    );
};

const PartiesSection = ({waybill}: {waybill: TransportWaybillDto}) => {
    const {t} = useTranslation();
    const partiesByRole = useMemo(() => groupPartiesByRole(waybill.parties || []), [waybill.parties]);
    const hasParties = Object.values(partiesByRole).some((parties) => parties && parties.length > 0);

    return (
        <Section>
            <SectionTitle>{t("Parties")}</SectionTitle>
            {!hasParties && <EmptyInline>{t("No parties extracted")}</EmptyInline>}
            {hasParties && (
                <CardsGrid>
                    {partyRoleOrder.flatMap((role) =>
                        (partiesByRole[role] || []).map((party) => (
                            <InfoCard key={party.id}>
                                <CardTitle>{t(getPartyRoleLabel(role, party.roleName))}</CardTitle>
                                {parseCompanySnapshot(party.counterpartyJson) && <CompanyCard company={parseCompanySnapshot(party.counterpartyJson)!}/>}
                                <FieldGrid>
                                    <DetailField label={t("Name")} value={party.name}/>
                                    <DetailField label={t("UNP")} value={party.unp}/>
                                    <DetailField label={t("Address")} value={party.address}/>
                                    <DetailField label={t("Registration number")} value={party.registrationNumber}/>
                                    <DetailField label={t("Contact name")} value={party.contactName}/>
                                    <DetailField label={t("Contact phone")} value={party.contactPhone}/>
                                    <DetailField label={t("Notes")} value={party.notes}/>
                                </FieldGrid>
                            </InfoCard>
                        )),
                    )}
                </CardsGrid>
            )}
        </Section>
    );
};

