const AuditSection = ({waybill, locale}: {waybill: TransportWaybillDto; locale: string}) => {
    const {t} = useTranslation();
    const attempts = waybill.processingAttempts || [];

    return (
        <Section>
            <SectionTitle>{t("Audit and debug")}</SectionTitle>
            <FieldGrid>
                <DetailField label={t("Original file")} value={waybill.file?.originalFileName}/>
                <DetailField label={t("Stored file name")} value={waybill.file?.storedFileName}/>
                <DetailField label={t("Server file path")} value={waybill.file?.storedFilePath}/>
                <DetailField label={t("Content type")} value={waybill.file?.contentType}/>
                <DetailField label={t("File size")} value={formatFileSize(waybill.file?.fileSizeBytes)}/>
                <DetailField label={t("Last modified")} value={formatDateTime(waybill.lastModifiedDateUtc, locale)}/>
            </FieldGrid>

            {attempts.length === 0 && <EmptyInline>{t("No processing attempts recorded")}</EmptyInline>}
            {attempts.length > 0 && (
                <TableWrap>
                    <DataTable>
                        <thead>
                        <tr>
                            <th>{t("Status")}</th>
                            <th>{t("Provider")}</th>
                            <th>{t("Model")}</th>
                            <th>{t("Prompt")}</th>
                            <th>{t("Started")}</th>
                            <th>{t("Finished")}</th>
                            <th>{t("Error")}</th>
                        </tr>
                        </thead>
                        <tbody>
                        {attempts.map((attempt) => (
                            <tr key={attempt.id}>
                                <td>{t(getProcessingAttemptStatusLabel(attempt.status, attempt.statusName))}</td>
                                <td>{attempt.provider}</td>
                                <td>{attempt.model}</td>
                                <td>{attempt.promptVersion}</td>
                                <td>{formatDateTime(attempt.startedDateUtc, locale)}</td>
                                <td>{formatDateTime(attempt.finishedDateUtc, locale)}</td>
                                <td>{attempt.errorMessage || emptyValue}</td>
                            </tr>
                        ))}
                        </tbody>
                    </DataTable>
                </TableWrap>
            )}

            <DebugDetails>
                <summary>{t("Raw recognized text")}</summary>
                <RawText>{waybill.rawRecognizedText || t("No raw text returned")}</RawText>
            </DebugDetails>
        </Section>
    );
};

const TransportWaybillDetail = ({goodsInvoice = false}: {goodsInvoice?: boolean}) => {
    const {id} = useParams();
    const {t, locale} = useTranslation();
    const waybillId = Number(id);
    const isValidId = Number.isInteger(waybillId) && waybillId > 0;
    const transport = useGetTransportWaybillByIdQuery(waybillId, {skip: !isValidId || goodsInvoice});
    const invoice = useGoodsInvoiceQuery(waybillId, {skip: !isValidId || !goodsInvoice});
    const {data: waybill, isLoading, isError} = goodsInvoice ? invoice : transport;

    if (!isValidId) {
        return (
            <MainDiv>
                <EmptyState>
                    <strong>{t("Waybill was not loaded")}</strong>
                    <span>{t("Check the waybill id or open it from the list.")}</span>
                </EmptyState>
            </MainDiv>
        );
    }

    if (isLoading) {
        return <Loader/>;
    }

    if (isError || !waybill) {
        return (
            <MainDiv>
                <EmptyState>
                    <strong>{t("Waybill was not loaded")}</strong>
                    <span>{t("Check backend availability or try again later.")}</span>
                </EmptyState>
            </MainDiv>
        );
    }

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{goodsInvoice ? "Файл для прихода" : t("Transport waybill")}</PageTitle>
                    <PageSubtitle>{goodsInvoice ? "Сверьте распознанные данные с оригиналом перед одобрением прихода." : t("Normalized document data returned by the backend extractor.")}</PageSubtitle>
                </PageTitleGroup>
            <TaskLink kind="document" id={id}/>
</PageHeader>
            <PageStack>
                {waybill.isArchived && <Alert severity="info">Файл для прихода в архиве. Его можно восстановить в списке файлов.</Alert>}
                <WaybillHeader waybill={waybill} locale={locale} goodsInvoice={goodsInvoice}/>
                <DocumentCounterparties document={waybill} onSaved={() => {void (goodsInvoice ? invoice : transport).refetch();}}/>
                {goodsInvoice && <OriginalInvoicePreview id={waybillId}/>}
                <PartiesSection waybill={waybill}/>
                {waybill.vehicle && <TransportSection waybill={waybill}/>}
                {waybill.cargoPoints.length > 0 && <CargoPointsSection waybill={waybill}/>}
                <GoodsSection waybill={waybill} locale={locale}/>
                <TotalsSection waybill={waybill} locale={locale}/>
                {waybill.operations.length > 0 && <OperationsSection waybill={waybill} locale={locale}/>}
                <details><summary>Технические сведения о распознавании</summary><AuditSection waybill={waybill} locale={locale}/></details>
            </PageStack>
        </MainDiv>
    );
};

export default TransportWaybillDetail;
